{"path": "dominoes.py", "content": "def can_chain(dominoes):
    """Return an ordered, oriented chain of dominoes (list of tuples)
    whose ends match, or None if impossible. Empty input gives []."""
    dominoes = [tuple(d) for d in dominoes]
    if not dominoes:
        return []

    def search(chain, remaining):
        if not remaining:
            return chain if chain[0][0] == chain[-1][1] else None
        end = chain[-1][1]
        tried = set()
        for i, (a, b) in enumerate(remaining):
            if (a, b) in tried:
                continue
            tried.add((a, b))
            rest = remaining[:i] + remaining[i + 1:]
            for x, y in ((a, b), (b, a)):
                if x == end:
                    result = search(chain + [(x, y)], rest)
                    if result:
                        return result
        return None

    first = dominoes[0]
    rest = dominoes[1:]
    return search([first], rest)
